inputs = ['wvj', 'kw', 'ugydjg', 'fx', 'zjvuij']
outputs = ['wifbj', 'kw', 'wyifbjg', 'fx', 'zjifbijij']

print("Detailed character-by-character analysis:")

for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"\nExample {i}: '{inp}' -> '{outp}'")
    if inp != outp:
        # Find the difference by position
        min_len = min(len(inp), len(outp))
        for j in range(min_len):
            if inp[j] != outp[j]:
                print(f"  Position {j}: '{inp[j]}' -> '{outp[j]}'")
                break
        # Check if lengths differ
        if len(inp) != len(outp):
            print(f"  Length change: {len(inp)} -> {len(outp)}")

        # Look for longer patterns
        print(f"  Full comparison:")
        for j in range(max(len(inp), len(outp))):
            in_char = inp[j] if j < len(inp) else "(end)"
            out_char = outp[j] if j < len(outp) else "(end)"
            if in_char != out_char:
                print(f"    Position {j}: '{in_char}' -> '{out_char}'")

